<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Support\Facades\DB;
class VoiceRecording extends Model { use HasUuid; protected $fillable=['voice_report_id','discord_guild_id','discord_channel_id','status','track_count','duration_seconds','size_bytes','captured_from','captured_until','deleted_at']; protected function casts(): array{return ['track_count'=>'integer','duration_seconds'=>'integer','size_bytes'=>'integer','captured_from'=>'datetime','captured_until'=>'datetime','deleted_at'=>'datetime'];} protected static function booted(): void {static::deleting(function(VoiceRecording $recording): void {$recording->tracks()->get()->each->delete();});} public function report(): BelongsTo{return $this->belongsTo(VoiceReport::class,'voice_report_id');} public function guild(): BelongsTo{return $this->belongsTo(DiscordGuild::class,'discord_guild_id');} public function channel(): BelongsTo{return $this->belongsTo(DiscordChannel::class,'discord_channel_id');} public function tracks(): HasMany{return $this->hasMany(VoiceAudioClip::class);} public function refreshSummary(): void { $tracks=$this->tracks()->get(); $this->update(['track_count'=>$tracks->count(),'duration_seconds'=>$tracks->max('duration_seconds')??0,'size_bytes'=>$tracks->sum('size_bytes'),'captured_from'=>$tracks->min('captured_from'),'captured_until'=>$tracks->max('captured_until'),'status'=>$tracks->contains(fn($track)=>$track->status==='failed')?'failed':($tracks->isEmpty()?'empty':'captured')]); } public function humanSize(): string {return number_format($this->size_bytes/1024/1024,2,',',' ').' Mo';} }
